//! Complete independent original dependency fold+emitter oracle. Legacy only.
pub use dq_analyze::{sem,tree,pat,util,reactive_facts,raw_marker_policy,lint,parity,incr,gens,pat_match};
#[path="support/deps_original/reaction_producer.rs"]pub mod original_reaction;
mod lints{pub use crate::original_reaction as derived_reads;}
use dq_analyze::gens::auto_tracked;
use std::{collections::BTreeSet,path::PathBuf};
#[path="support/deps_original/projected.rs"]mod original;
fn legacy_canonical_read_key(kind: &dq_analyze::sem::reads::ReadKind, name: &str, capability_keys: &BTreeSet<String>, defines: &BTreeSet<String>) -> String {
    if *kind == dq_analyze::sem::reads::ReadKind::Accessor && capability_keys.contains(name) {
        format!("capkey:[{name}]")
    } else if *kind == dq_analyze::sem::reads::ReadKind::Accessor && defines.contains(name) {
        format!("[{name}]")
    } else {
        name.to_string()
    }
}

fn full_facts(a:&reactive_facts::DepsAnalysis)->serde_json::Value{serde_json::json!({
 "consumers":a.consumers.iter().collect::<Vec<_>>(),"draws":a.draws.iter().collect::<Vec<_>>(),"leaves":a.leaves,
 "draw_reads":a.draw_reads.iter().map(|(k,v)|(k,v.iter().collect::<Vec<_>>())).collect::<Vec<_>>(),
 "draw_keys":a.draw_keys.iter().map(|(k,v)|(k,v.iter().collect::<Vec<_>>())).collect::<Vec<_>>(),
 "draw_hops":a.draw_hops.iter().map(|(k,v)|(k,v.iter().collect::<Vec<_>>())).collect::<Vec<_>>(),
 "draw_links":a.draw_links.iter().map(|(k,v)|(k,v.iter().collect::<Vec<_>>())).collect::<Vec<_>>(),
 "verb_reads":a.verb_reads.iter().map(|(k,(v,b))|(k,(v.iter().collect::<Vec<_>>(),b))).collect::<Vec<_>>(),
 "stat_reads":a.stat_reads.iter().collect::<Vec<_>>(),"reads":a.reads.iter().collect::<Vec<_>>(),"candidates":a.candidates.iter().collect::<Vec<_>>(),
 "sampled":a.sampled.iter().map(|(k,v)|(k,v.iter().collect::<Vec<_>>())).collect::<Vec<_>>()})}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let expected_projection=include_str!("support/deps_original/producer.rs").replace("tree.memo(\"gen/deps\", || compute(tree, true))","std::sync::Arc::new(compute(tree, true))").replace("tree.memo(\"gen/deps-legacy\", || compute(tree, false))","std::sync::Arc::new(compute(tree, false))").replace("crate::gens::reads::canonical_read_key","crate::legacy_canonical_read_key").replace("eng.sem.file_of(p.get().location) == Some(super::auto_tracked::AUTO_REL)","!p.get().location.is_builtins() && eng.sem.rel(p.get().location) == super::auto_tracked::AUTO_REL");
 assert_eq!(include_str!("support/deps_original/projected.rs"),expected_projection,"only declared original-cache bypass and nominal private helper projection may differ");
 let root=PathBuf::from(std::env::args().nth(1).ok_or("fixture root required")?);let root=if root.is_absolute(){root}else{std::env::current_dir()?.join(root)};
 let engine=dq_analyze::run::Engine::new(dq_analyze::run::registry(),dq_analyze::run::Options{root:root.clone(),scopes_from:Some(root.clone()),raw:true,no_cache:true,..Default::default()})?;
 let sem=sem::sem_for(&engine.tree).ok_or("independent old semantic owner absent")?;if !sem.errors.is_empty(){return Err(format!("independent old parse errors: {:?}",sem.errors).into())}
 let result=original::analyzed(&engine.tree);let facts=result.as_ref().as_ref().ok_or("independent old complete dependency result absent")?;
 if facts.draws.is_empty()||facts.consumers.is_empty(){return Err("old whole dependency fixture must exercise actual draw consumer".into())}
 let mut generators=Vec::new();original::register(&mut generators);let generator=generators.iter().find(|g|g.name()=="deps").ok_or("old deps generator missing")?;
 let cx=sem::gen::GenCx::new(&engine.tree,&root);let mut output=sem::gen::GenOut::default();generator.generate(&cx,&mut output);
 let mut text=format!("// GENERATED by tools/analyze: \x60analyze gen {}\x60. Do not edit by hand; edit the declarations it reads.\n// Written to code/engine/_generated/{}; not committed: every build regenerates it (\x60analyze gen\x60).\n\n",generator.name(),generator.output());text.push_str(output.text());if !text.ends_with('\n'){text.push('\n')}
 let full=serde_json::json!({"facts":full_facts(facts),"artifact":{"path":format!("code/engine/_generated/{}",generator.output()),"text":text,"diagnostics":output.diags.iter().map(|d|(&d.rel,d.line,&d.msg)).collect::<Vec<_>>()}});
 println!("OLD_DEPS_FULL={}",serde_json::to_string(&full)?);Ok(())
}
